/****************************************************************************
 * Name: lv_nuttx_init_custom
 *
 * Description:
 *   Custom LVGL NuttX initialization for the SiFli SF32LB52 board.
 *   Opens the LCD framebuffer and touchscreen input device.
 *
 * Input Parameters:
 *   dsc    - Pointer to the LVGL NuttX descriptor
 *   result - Pointer to the result structure
 *
 ****************************************************************************/

void lv_nuttx_init_custom(const lv_nuttx_dsc_t *dsc,
                          lv_nuttx_result_t *result)
{
  if (result)
    {
      lv_memzero(result, sizeof(lv_nuttx_result_t));
    }

  if (dsc && dsc->fb_path)
    {
      lv_display_t *disp = NULL;

#ifdef CONFIG_LV_USE_NUTTX_LCD
      disp = lv_nuttx_lcd_create(dsc->fb_path);
#else
      disp = lv_nuttx_fbdev_create();
      if (lv_nuttx_fbdev_set_file(disp, dsc->fb_path) != 0)
        {
          lv_display_delete(disp);
          disp = NULL;
        }
#endif

      if (result)
        {
          result->disp = disp;
        }
    }

  if (dsc)
    {
#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
      if (dsc->input_path)
        {
          lv_indev_t *indev =
              lv_nuttx_touchscreen_create(dsc->input_path);
          if (result)
            {
              result->indev = indev;
            }
        }

      if (dsc->utouch_path)
        {
          lv_indev_t *indev =
              lv_nuttx_touchscreen_create(dsc->utouch_path);
          if (result)
            {
              result->utouch_indev = indev;
            }
        }
#endif

#ifdef CONFIG_LV_USE_NUTTX_MOUSE
      if (dsc->mouse_path)
        {
          lv_indev_t *indev = lv_nuttx_mouse_create(dsc->mouse_path);
          if (result)
            {
              result->mouse_indev = indev;
            }
        }
#endif
    }
}

/****************************************************************************
 * Name: lv_nuttx_deinit_custom
 *
 * Description:
 *   Custom LVGL NuttX deinitialization for the SiFli SF32LB52 board.
 *
 ****************************************************************************/

void lv_nuttx_deinit_custom(lv_nuttx_result_t *result)
{
  if (result)
    {
      if (result->disp)
        {
          lv_display_delete(result->disp);
          result->disp = NULL;
        }

      if (result->indev)
        {
          lv_indev_delete(result->indev);
          result->indev = NULL;
        }

      if (result->utouch_indev)
        {
          lv_indev_delete(result->utouch_indev);
          result->utouch_indev = NULL;
        }

      if (result->mouse_indev)
        {
          lv_indev_delete(result->mouse_indev);
          result->mouse_indev = NULL;
        }
    }
}

